function parseCsv(text){return window.FinloCore.csv.parseCsv(text).filter(r=>r.some(x=>String(x).trim()))}
function autoMap(headers){const h=headers.map(x=>norm(x));const find=terms=>h.findIndex(x=>terms.some(t=>x.includes(t)));const amount=find(['amount','value']);return{date:find(['date','transaction date','posted']),amount,debit:amount>=0?-1:find(['debit','withdrawal','money out']),credit:amount>=0?-1:find(['credit','deposit','money in']),description:find(['description','details','memo','particular']),reference:find(['reference','ref','code']),payee:find(['payee','name','merchant']),id:find(['transaction id','bank id','unique id'])}}
function mappingSelect(label,key,headers,value){return `<label>${label}<select data-br-map="${key}"><option value="-1">Not mapped</option>${headers.map((h,i)=>`<option value="${i}" ${i===value?'selected':''}>${esc(h)}</option>`).join('')}</select></label>`}
function parseDate(v){v=String(v||'').trim();let m;if((m=v.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})/)))return `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;if((m=v.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{2,4})/))){let y=m[3];if(y.length===2)y='20'+y;return `${y}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`}const d=new Date(v);return isNaN(d)?'':d.toISOString().slice(0,10)}
function mappedRows(){if(!state.csv)return[];const m=state.mapping;return state.csv.rows.map((r,i)=>{let amount=m.amount>=0?num(String(r[m.amount]||'').replace(/[$, ]/g,'')):0;if(m.amount<0){const cr=m.credit>=0?num(String(r[m.credit]||'').replace(/[$, ]/g,'')):0,dr=m.debit>=0?num(String(r[m.debit]||'').replace(/[$, ]/g,'')):0;amount=cr-dr}const x={row:i+2,transaction_date:parseDate(r[m.date]),amount,description:m.description>=0?r[m.description]:'',reference:m.reference>=0?r[m.reference]:'',payee:m.payee>=0?r[m.payee]:'',bank_transaction_id:m.id>=0?r[m.id]:''};x.import_fingerprint=fingerprint(x);return x}).filter(x=>x.transaction_date&&x.amount)}
