  $('brDepositRefundTx').onchange=sync;$('brDepositRefundCancel').onclick=()=>$('bankReconModal').classList.remove('open');sync();
  $('brDepositRefundSave').onclick=async()=>{const btn=$('brDepositRefundSave'),refundId=$('brDepositRefundTx').value,expenseId=$('brDepositRefundExpense').value;if(!refundId||!expenseId)return toast('Select the refund and the matching expense.');btn.disabled=true;btn.textContent='Reconciling...';const {data,error}=await sb.rpc('v61107i_reconcile_expense_deposit_refund',{p_money_out_transaction_id:txid,p_refund_transaction_id:refundId,p_expense_id:expenseId,p_note:$('brDepositRefundNote').value.trim()||null});if(error){btn.disabled=false;btn.textContent='Reconcile Deposit / Refund';return toast(error.message)}$('bankReconModal').classList.remove('open');window.Expenses?.refresh?.();toast(`Deposit and refund reconciled. Net expense ${money(num(data?.net_expense))}`);loadQueue()};
